//! What the twin knows about a device, and what it reports when something changes.
//!
//! Every string a device supplied has already been through
//! [`clean_device_text`](crate::text::clean_device_text), but it's still the device's
//! claim, not a fact: show it as data and never build commands from it.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

/// Generated by the service (`dev_<id>`). Never derived from an IP or a name, since those
/// change, and cells often reuse the same subnet.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub struct DeviceId(pub String);

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum DeviceClass {
    Plc,
    Hmi,
    Pc,
    Switch,
    Drive,
    Sensor,
    IoLinkMaster,
    Gateway,
    Robot,
    Cnc,
    Meter,
    Unknown,
}

impl DeviceClass {
    pub const ALL: [Self; 12] = [Self::Plc, Self::Hmi, Self::Pc, Self::Switch, Self::Drive, Self::Sensor, Self::IoLinkMaster, Self::Gateway, Self::Robot, Self::Cnc, Self::Meter, Self::Unknown];

    pub fn label(self) -> &'static str {
        match self {
            Self::Plc => "PLC",
            Self::Hmi => "HMI",
            Self::Pc => "PC",
            Self::Switch => "Switch",
            Self::Drive => "Drive",
            Self::Sensor => "Sensor",
            Self::IoLinkMaster => "IO-Link master",
            Self::Gateway => "Gateway",
            Self::Robot => "Robot",
            Self::Cnc => "CNC",
            Self::Meter => "Meter",
            Self::Unknown => "Unknown",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum Liveness {
    /// Never checked yet.
    Unknown,
    Up,
    /// Missed some checks, not yet called down.
    Suspect,
    /// Failed checks from every healthy vantage point.
    Down,
    /// The vantage point that watches it is gone, so its state isn't known.
    Stale,
    /// Removed from the inventory by an operator.
    Retired,
}

impl Liveness {
    pub fn label(self) -> &'static str {
        match self {
            Self::Unknown => "Unknown",
            Self::Up => "Up",
            Self::Suspect => "Suspect",
            Self::Down => "Down",
            Self::Stale => "Stale",
            Self::Retired => "Retired",
        }
    }
}

/// How much the twin can do with a device. Each level needs more from the device.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum Coverage {
    /// IP, MAC, vendor, up/down.
    Counted,
    /// Model, serial, firmware.
    Identified,
    /// Mode, tags, alarms.
    Monitored,
    /// Commands with read-back.
    Controlled,
}

impl Coverage {
    pub fn label(self) -> &'static str {
        match self {
            Self::Counted => "Counted",
            Self::Identified => "Identified",
            Self::Monitored => "Monitored",
            Self::Controlled => "Controlled",
        }
    }
}

/// Everything here is what the device claims about itself.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Identity {
    pub vendor: Option<String>,
    pub model: Option<String>,
    pub order_number: Option<String>,
    pub serial: Option<String>,
    pub firmware: Option<String>,
    pub station_name: Option<String>,
}

/// Where a device was seen. An IP only means something together with its vantage point.
#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Address {
    pub vantage: String,
    pub ip: Option<String>,
    pub mac: Option<String>,
}

/// A device reached through another one, such as a sensor on an IO-Link master's port.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Parent {
    pub device: DeviceId,
    pub port: u32,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Device {
    pub id: DeviceId,
    pub class: DeviceClass,
    pub liveness: Liveness,
    pub coverage: Coverage,
    #[serde(default)]
    pub identity: Identity,
    #[serde(default)]
    pub addresses: Vec<Address>,
    /// Operating mode as the device reports it, such as `run`.
    #[serde(default)]
    pub mode: Option<String>,
    #[serde(default)]
    pub parent: Option<Parent>,
    /// Milliseconds since the Unix epoch.
    #[serde(default)]
    pub last_seen_ms: Option<u64>,
    /// Inventory revision of the last change, set by [`Inventory`](crate::inventory::Inventory).
    #[serde(default)]
    pub rev: u64,
}

impl Device {
    /// The best name available, falling back to the IP, then the generated ID.
    pub fn name(&self) -> &str {
        let identity = &self.identity;
        identity.station_name.as_deref().or(identity.model.as_deref()).or(self.ip()).unwrap_or(&self.id.0)
    }

    pub fn ip(&self) -> Option<&str> {
        self.addresses.iter().find_map(|a| a.ip.as_deref())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Initiator {
    /// Changed outside the twin, for example from TIA Portal or the mode selector.
    External,
    /// Changed through the operator console.
    Operator,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum EventKind {
    Appeared,
    Down,
    Recovered,
    IdentityChanged,
    AddressChanged,
    /// A known address now answers with a different serial.
    Replaced,
    ModeChanged { initiator: Initiator },
    SoftwareChanged,
    VantageLost,
    SegmentDown,
    CommandExecuted,
    ScanCompleted,
}

impl EventKind {
    pub fn label(self) -> &'static str {
        match self {
            Self::Appeared => "Appeared",
            Self::Down => "Down",
            Self::Recovered => "Recovered",
            Self::IdentityChanged => "Identity changed",
            Self::AddressChanged => "Address changed",
            Self::Replaced => "Replaced",
            Self::ModeChanged { .. } => "Mode changed",
            Self::SoftwareChanged => "Software changed",
            Self::VantageLost => "Vantage point lost",
            Self::SegmentDown => "Segment down",
            Self::CommandExecuted => "Command executed",
            Self::ScanCompleted => "Scan completed",
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub enum Severity {
    Info,
    Warning,
    Critical,
}

/// Before the inventory numbers it. See [`Inventory::record`](crate::inventory::Inventory::record).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct NewEvent {
    pub ts_ms: u64,
    pub kind: EventKind,
    pub severity: Severity,
    pub device_id: Option<DeviceId>,
    pub vantage: Option<String>,
    pub before: Option<String>,
    pub after: Option<String>,
    pub correlation_id: Option<String>,
    pub untrusted: BTreeMap<String, String>,
}

impl NewEvent {
    pub fn new(ts_ms: u64, kind: EventKind, severity: Severity, device_id: Option<DeviceId>) -> Self {
        Self { ts_ms, kind, severity, device_id, vantage: None, before: None, after: None, correlation_id: None, untrusted: BTreeMap::new() }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Event {
    /// Increases by one per event, across restarts.
    pub seq: u64,
    pub ts_ms: u64,
    pub kind: EventKind,
    pub severity: Severity,
    #[serde(default)]
    pub device_id: Option<DeviceId>,
    #[serde(default)]
    pub vantage: Option<String>,
    #[serde(default)]
    pub before: Option<String>,
    #[serde(default)]
    pub after: Option<String>,
    #[serde(default)]
    pub correlation_id: Option<String>,
    /// Cleaned device text. Hooks receive device text only through this field.
    #[serde(default)]
    pub untrusted: BTreeMap<String, String>,
}
